"""Stage 9: verify bibliographic metadata of the pre-FM comparison works that are not yet in the bibliography.
Crossref bibliographic query by title; a record is accepted only if the normalised title matches exactly (or with similarity >= 0.95)
and the year differs by at most 1. Nothing is invented: unmatched works are reported and not written as verified.
Output: 13_References/prefm_verified.json (consumed by 13_References/build_bib.py)."""
import json, os, re, time, difflib, urllib.request, urllib.parse, csv
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.abspath(os.path.join(HERE, '..', '..', '..'))
EXISTING = {'Sisbot2007HAMP': 'Sisbot2007SisbotHAMP', 'Mavrogiannis2018SocialMomentum': 'Mavrogiannis2018SocialMomentum', 'Mavrogiannis2019HRI': 'Mavrogiannis2019MavrogiannisHRI2019',
            'Wang2021GMPC': 'Wang2022GMPC', 'Pellegrini2009YNWA': 'Pellegrini2009ETH', 'Alahi2016SocialLSTM': 'al2016SocialLSTM', 'Everett2018GA3C': 'Everett2018GA3CCADRL', 'Chen2020RGL': 'Chen2020RGL'}
TITLE = {'vandenBerg2008RVO': 'Reciprocal Velocity Obstacles for real-time multi-agent navigation', 'Thrun1999Minerva': 'Probabilistic Algorithms and the Interactive Museum Tour-Guide Robot Minerva',
         'Pandey2010Framework': 'A framework towards a socially aware Mobile Robot motion in Human-Centered dynamic environment', 'Svenstrup2010Trajectory': 'Trajectory planning for robots in dynamic human environments',
         'Pacchierotti2006Passing': 'Evaluation of Passing Distance for Social Robots', 'Chung2010Spatial': 'A mobile robot that understands pedestrian spatial behaviors',
         'Charalampous2016SocialMaps': 'Robot navigation in large-scale social maps: An action recognition approach',
         'Shiomi2014Acceptable': 'Towards a Socially Acceptable Collision Avoidance for a Mobile Robot Navigating Among Pedestrians Using a Pedestrian Model',
         'Ferrer2013Companion': 'Robot companion: A social-force based approach with human awareness-navigation in crowded environments',
         'Truong2017Approach': 'To Approach Humans?: A Unified Framework for Approaching Pose Prediction and Socially Aware Robot Navigation', 'Katyal2022GroupAware': 'Learning a Group-Aware Policy for Robot Navigation',
         'Vemula2018SocialAttention': 'Social Attention: Modeling Attention in Human Crowds', 'Henry2010Crowded': 'Learning to navigate through crowded environments',
         'Vasquez2014IRLFeatures': 'Inverse Reinforcement Learning algorithms and features for robot navigation in crowds: An experimental comparison',
         'Kim2016SociallyAdaptive': 'Socially Adaptive Path Planning in Human Environments Using Inverse Reinforcement Learning', 'Luber2012Learning': 'Socially-aware robot navigation: A learning approach',
         'Hamandi2019DeepMoTIon': 'DeepMoTIon: Learning to Navigate Like Humans', 'Liu2020DRLCrowded': 'Robot Navigation in Crowded Environments Using Deep Reinforcement Learning',
         'Sathyamoorthy2020Frozone': 'Frozone: Freezing-Free, Pedestrian-Friendly Navigation in Human Crowds',
         'Brito2021Subgoal': 'Where to Go Next: Learning a Subgoal Recommendation Policy for Navigation in Dynamic Environments'}
YEAR = {r['key']: int(r['year']) for r in csv.DictReader(open(os.path.join(ROOT, '07_Literature_Analysis', 'prefm_comparison_set.csv')))}
def norm(s): return re.sub(r'[^a-z0-9]', '', re.sub(r'<[^>]+>', '', str(s)).lower())
def tex(s):
    for a, b in [('&', r'\&'), ('%', r'\%'), ('#', r'\#'), ('_', r'\_')]: s = s.replace(a, b)
    return s
def query(t):
    u = 'https://api.crossref.org/works?' + urllib.parse.urlencode({'query.bibliographic': t, 'rows': 5})
    for _ in range(3):
        try: return json.load(urllib.request.urlopen(u, timeout=40))['message']['items']
        except Exception: time.sleep(5)
    return []
def main():
    out = {'_doc': 'Verified metadata for pre-FM comparison works (Stage 9); generated by 07_Literature_Analysis/_tools/stage9/verify_prefm_refs.py', '_existing_keys': EXISTING}
    for k, t in TITLE.items():
        best = None
        for it in query(t):
            ti = (it.get('title') or [''])[0]; sim = difflib.SequenceMatcher(None, norm(ti), norm(t)).ratio()
            yr = ((it.get('published-print') or it.get('published-online') or it.get('issued') or {}).get('date-parts') or [[None]])[0][0]
            if sim >= 0.95 and yr and abs(yr - YEAR[k]) <= 1 and (best is None or sim > best[0]): best = (sim, it, yr)
        if not best: out[k] = {'status': 'NOT VERIFIED'}; print(k, 'NOT VERIFIED'); time.sleep(1); continue
        sim, it, yr = best; typ = {'journal-article': 'article', 'proceedings-article': 'inproceedings'}.get(it['type'], 'incollection')
        au = ' and '.join(tex(f"{a.get('family', '')}, {a.get('given', '')}".strip(', ')) for a in it.get('author', []))
        F = {'author': au, 'title': '{' + tex((it.get('title') or [''])[0]) + '}', 'year': str(yr)}
        F['journal' if typ == 'article' else 'booktitle'] = tex((it.get('container-title') or [''])[0])
        if typ == 'article' and it.get('volume'): F['volume'] = it['volume']
        if typ == 'article' and it.get('issue'): F['number'] = it['issue']
        if it.get('page'): F['pages'] = it['page'].replace('-', '--')
        F['doi'] = it['DOI']; F['publisher'] = it.get('publisher', '')
        out[k] = {'status': 'VERIFIED', 'type': typ, 'similarity': round(sim, 3), 'fields': {a: b for a, b in F.items() if b}, 'source': 'Crossref https://doi.org/' + it['DOI']}
        print(k, 'OK', it['DOI'], (it.get('container-title') or [''])[0][:60], round(sim, 3)); time.sleep(1)
    json.dump(out, open(os.path.join(ROOT, '13_References', 'prefm_verified.json'), 'w'), indent=1)
if __name__ == '__main__': main()
